160	/****************************************************************************
161	 * Name: dhcpc_add<option>
162	 ****************************************************************************/
163	
164	static FAR uint8_t *dhcpc_addhostname(FAR const char *hostname,
165	                                      FAR uint8_t *optptr)
166	{
167	  int len = strlen(hostname);
168	  *optptr++ = DHCP_OPTION_HOST_NAME;
169	  *optptr++ = len;
170	  memcpy(optptr, hostname, len);
171	  return optptr + len;
172	}
173	
174	static FAR uint8_t *dhcpc_addmsgtype(FAR uint8_t *optptr, uint8_t type)
175	{
176	  *optptr++ = DHCP_OPTION_MSG_TYPE;
177	  *optptr++ = 1;
178	  *optptr++ = type;
179	  return optptr;
180	}
181	
182	static FAR uint8_t *dhcpc_addserverid(FAR struct in_addr *serverid,
183	                                      FAR uint8_t *optptr)
184	{
185	  *optptr++ = DHCP_OPTION_SERVER_ID;
186	  *optptr++ = 4;
187	  memcpy(optptr, &serverid->s_addr, 4);
188	  return optptr + 4;
189	}
190	
191	static FAR uint8_t *dhcpc_addreqipaddr(FAR struct in_addr *ipaddr,
192	                                       FAR uint8_t *optptr)
193	{
194	  *optptr++ = DHCP_OPTION_REQ_IPADDR;
195	  *optptr++ = 4;
196	  memcpy(optptr, &ipaddr->s_addr, 4);
197	  return optptr + 4;
198	}
199	
200	static FAR uint8_t *dhcpc_addclientid(FAR uint8_t *clientid,
201	                                      FAR uint8_t len,
202	                                      FAR uint8_t *optptr)
203	{
204	  *optptr++ = DHCP_OPTION_CLIENT_ID;
205	  *optptr++ = 1 + len;
206	  *optptr++ = 0x1;
207	  memcpy(optptr, clientid, len);
208	  return optptr + len;
209	}
210	
211	static FAR uint8_t *dhcpc_addreqoptions(FAR uint8_t *optptr)
212	{
213	  *optptr++ = DHCP_OPTION_REQ_LIST;
214	  *optptr++ = 3;
215	  *optptr++ = DHCP_OPTION_SUBNET_MASK;
216	  *optptr++ = DHCP_OPTION_ROUTER;
217	  *optptr++ = DHCP_OPTION_DNS_SERVER;
218	  return optptr;
219	}
220	
221	static FAR uint8_t *dhcpc_addend(FAR uint8_t *optptr)
222	{
223	  *optptr++ = DHCP_OPTION_END;
224	  return optptr;
225	}
