227	/****************************************************************************
228	 * Name: dhcpc_sendmsg
229	 ****************************************************************************/
230	
231	static int dhcpc_sendmsg(FAR struct dhcpc_state_s *pdhcpc,
232	                         FAR struct dhcpc_state *presult, int msgtype)
233	{
234	  char hostname[HOST_NAME_MAX + 1];
235	  struct sockaddr_in addr;
236	  FAR uint8_t *pend;
237	  in_addr_t serverid = INADDR_BROADCAST;
238	  int len;
239	
240	  /* Create the common message header settings */
241	
242	  memset(&pdhcpc->packet, 0, sizeof(struct dhcp_msg));
243	  pdhcpc->packet.op    = DHCP_REQUEST;
244	  pdhcpc->packet.htype = DHCP_HTYPE_ETHERNET;
245	  pdhcpc->packet.hlen  = pdhcpc->maclen;
246	  memcpy(pdhcpc->packet.xid, pdhcpc->xid, 4);
247	  memcpy(pdhcpc->packet.chaddr, pdhcpc->macaddr, pdhcpc->maclen);
248	  memset(&pdhcpc->packet.chaddr[pdhcpc->maclen], 0, 16 - pdhcpc->maclen);
249	  memcpy(pdhcpc->packet.options, magic_cookie, sizeof(magic_cookie));
250	
251	  /* Add the common header options */
252	
253	  pend = &pdhcpc->packet.options[4];
254	  pend = dhcpc_addmsgtype(pend, msgtype);
255	
256	  /* Get the current host name */
257	
258	  if (gethostname(hostname, sizeof(hostname)) || (0 == strlen(hostname)))
259	    {
260	      strlcpy(hostname, CONFIG_NETUTILS_DHCPC_HOST_NAME, sizeof(hostname));
261	    }
262	
263	  /* Handle the message specific settings */
264	
265	  switch (msgtype)
266	    {
267	      /* Broadcast DISCOVER message to all servers */
268	
269	      case DHCPDISCOVER:
270	        /* Socket binded to INADDR_ANY is not intended to receive unicast
271	         * traffic before being fully configured, at least dhclient
272	         * configured with socket-only won't do so on Linux and BSDs.
273	         * We can sometimes receive unicast traffic before being fully
274	         * configured, it's good, but not always, so we need to set the
275	         * broadcast flag under some situations.
276	         */
277	
278	        /* Broadcast bit. */
279	
280	        pdhcpc->packet.flags = HTONS(CONFIG_NETUTILS_DHCPC_BOOTP_FLAGS);
281	
282	        pend     = dhcpc_addhostname(hostname, pend);
283	        pend     = dhcpc_addreqoptions(pend);
284	        pend     = dhcpc_addclientid(pdhcpc->macaddr, pdhcpc->maclen, pend);
285	        break;
286	
287	      /* Send REQUEST message to the server that sent the *first* OFFER */
288	
289	      case DHCPREQUEST:
290	
291	        /* Broadcast bit. */
292	
293	        pdhcpc->packet.flags = HTONS(CONFIG_NETUTILS_DHCPC_BOOTP_FLAGS);
294	
295	        pend     = dhcpc_addhostname(hostname, pend);
296	        pend     = dhcpc_addserverid(&pdhcpc->serverid, pend);
297	        pend     = dhcpc_addreqipaddr(&pdhcpc->ipaddr, pend);
298	        pend     = dhcpc_addclientid(pdhcpc->macaddr, pdhcpc->maclen, pend);
299	        break;
300	
301	      /* Send DECLINE message to the server that sent the *last* OFFER */
302	
303	      case DHCPDECLINE:
304	        memcpy(pdhcpc->packet.ciaddr, &presult->ipaddr.s_addr, 4);
305	        pend     = dhcpc_addserverid(&presult->serverid, pend);
306	        serverid = presult->serverid.s_addr;
307	        break;
308	
309	      default:
310	        errno = EINVAL;
311	        return ERROR;
312	    }
313	
314	  pend = dhcpc_addend(pend);
315	  len  = pend - (uint8_t *)&pdhcpc->packet;
316	
317	  /* Send the request */
318	
319	  addr.sin_family      = AF_INET;
320	  addr.sin_port        = HTONS(DHCPC_SERVER_PORT);
321	  addr.sin_addr.s_addr = serverid;
322	
323	  return sendto(pdhcpc->sockfd, &pdhcpc->packet, len, 0,
324	                (struct sockaddr *)&addr, sizeof(struct sockaddr_in));
325	}
