327	/****************************************************************************
328	 * Name: dhcpc_parseoptions
329	 ****************************************************************************/
330	
331	static uint8_t dhcpc_parseoptions(FAR struct dhcpc_state *presult,
332	                                  FAR uint8_t *optptr, int len)
333	{
334	  FAR uint8_t *end = optptr + len;
335	  uint8_t type = 0;
336	
337	  while (optptr < end)
338	    {
339	      switch (*optptr)
340	        {
341	          case DHCP_OPTION_SUBNET_MASK:
342	
343	            /* Get subnet mask in network order */
344	
345	            if (optptr + 6 <= end)
346	              {
347	                memcpy(&presult->netmask.s_addr, optptr + 2, 4);
348	              }
349	            else
350	              {
351	                nerr("Packet too short (netmask missing)\n");
352	              }
353	            break;
354	
355	          case DHCP_OPTION_ROUTER:
356	
357	            /* Get the default router address in network order */
358	
359	            if (optptr + 6 <= end)
360	              {
361	                memcpy(&presult->default_router.s_addr, optptr + 2, 4);
362	              }
363	            else
364	              {
365	                nerr("Packet too short (router address missing)\n");
366	              }
367	            break;
368	
369	          case DHCP_OPTION_DNS_SERVER:
370	
371	            /* Get the DNS server address in network order */
372	
373	            if (optptr + 6 <= end)
374	              {
375	                memcpy(&presult->dnsaddr.s_addr, optptr + 2, 4);
376	              }
377	            else
378	              {
379	                nerr("Packet too short (DNS address missing)\n");
380	              }
381	            break;
382	
383	          case DHCP_OPTION_MSG_TYPE:
384	
385	            /* Get message type */
386	
387	            if (optptr + 3 <= end)
388	              {
389	                type = *(optptr + 2);
390	              }
391	            else
392	              {
393	                nerr("Packet too short (type missing)\n");
394	              }
395	            break;
396	
397	          case DHCP_OPTION_SERVER_ID:
398	
399	            /* Get server address in network order */
400	
401	            if (optptr + 6 <= end)
402	              {
403	                memcpy(&presult->serverid.s_addr, optptr + 2, 4);
404	              }
405	            else
406	              {
407	                nerr("Packet too short (server address missing)\n");
408	              }
409	            break;
410	
411	          case DHCP_OPTION_LEASE_TIME:
412	
413	              /* Get lease time (in seconds) in host order */
414	
415	            if (optptr + 6 <= end)
416	              {
417	                uint16_t tmp[2];
418	                memcpy(tmp, optptr + 2, 4);
419	                presult->lease_time = ((uint32_t)ntohs(tmp[0])) << 16 |
420	                                       (uint32_t)ntohs(tmp[1]);
421	              }
422	            else
423	              {
424	                nerr("Packet too short (lease time missing)\n");
425	              }
426	            break;
427	
428	          case DHCP_OPTION_END:
429	            return type;
430	        }
431	
432	      if (optptr + 1 >= end)
433	        {
434	          break;
435	        }
436	
437	      optptr += optptr[1] + 2;
438	    }
439	
440	  return type;
441	}
