443	/****************************************************************************
444	 * Name: dhcpc_parsemsg
445	 ****************************************************************************/
446	
447	static uint8_t dhcpc_parsemsg(FAR struct dhcpc_state_s *pdhcpc, int buflen,
448	                              FAR struct dhcpc_state *presult)
449	{
450	  if (buflen >= 44 && pdhcpc->packet.op == DHCP_REPLY &&
451	      memcmp(pdhcpc->packet.xid, pdhcpc->xid, 4) == 0 &&
452	      memcmp(pdhcpc->packet.chaddr,
453	             pdhcpc->macaddr, pdhcpc->maclen) == 0)
454	    {
455	      memcpy(&presult->ipaddr.s_addr, pdhcpc->packet.yiaddr, 4);
456	      return dhcpc_parseoptions(presult, &pdhcpc->packet.options[4],
457	                                buflen -
458	                                (offsetof(struct dhcp_msg, options) + 4));
459	    }
460	
461	  return 0;
462	}
