464	/****************************************************************************
465	 * Name: dhcpc_run
466	 ****************************************************************************/
467	
468	static void *dhcpc_run(void *args)
469	{
470	  FAR struct dhcpc_state_s *pdhcpc = (FAR struct dhcpc_state_s *)args;
471	  struct dhcpc_state result;
472	  int ret;
473	
474	#ifdef CONFIG_DISABLE_SIGNALS
475	  pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);
476	  pthread_setcanceltype(PTHREAD_CANCEL_DEFERRED, NULL);
477	#endif
478	
479	  while (1)
480	    {
481	#ifdef CONFIG_DISABLE_SIGNALS
482	      pthread_testcancel();
483	#endif
484	      ret = dhcpc_request(pdhcpc, &result);
485	      if (ret == OK)
486	        {
487	          pdhcpc->callback(&result);
488	        }
489	      else
490	        {
491	          pdhcpc->callback(NULL);
492	          memset(&result, 0, sizeof(result));
493	          nerr("dhcpc_request error\n");
494	        }
495	
496	      if (pdhcpc->cancel)
497	        {
498	          return NULL;
499	        }
500	
501	      result.lease_time /= 2;
502	      while (result.lease_time)
503	        {
504	          result.lease_time = sleep(result.lease_time);
505	          if (pdhcpc->cancel)
506	            {
507	              return NULL;
508	            }
509	        }
510	    }
511	
512	  return NULL;
513	}
