519	/****************************************************************************
520	 * Name: dhcpc_open
521	 ****************************************************************************/
522	
523	FAR void *dhcpc_open(FAR const char *interface, FAR const void *macaddr,
524	                     int maclen)
525	{
526	  FAR struct dhcpc_state_s *pdhcpc;
527	  struct sockaddr_in addr;
528	  struct timeval tv;
529	  int ret;
530	
531	  ninfo("MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
532	        ((uint8_t *)macaddr)[0], ((uint8_t *)macaddr)[1],
533	        ((uint8_t *)macaddr)[2], ((uint8_t *)macaddr)[3],
534	        ((uint8_t *)macaddr)[4], ((uint8_t *)macaddr)[5]);
535	
536	  /* Allocate an internal DHCP structure */
537	
538	  pdhcpc = malloc(sizeof(struct dhcpc_state_s) + maclen - 1);
539	  if (pdhcpc)
540	    {
541	      /* Initialize the allocated structure */
542	
543	      memset(pdhcpc, 0, sizeof(struct dhcpc_state_s));
544	
545	      /* RFC2131: A DHCP client MUST choose 'xid's in such a
546	       * way as to minimize the chance of using an 'xid' identical to one
547	       * used by another client.
548	       */
549	
550	      arc4random_buf(pdhcpc->xid, 4);
551	
552	      pdhcpc->interface = interface;
553	      pdhcpc->maclen    = maclen;
554	      memcpy(pdhcpc->macaddr, macaddr, pdhcpc->maclen);
555	
556	      /* Create a UDP socket */
557	
558	      pdhcpc->sockfd = socket(PF_INET, SOCK_DGRAM | SOCK_CLOEXEC, 0);
559	      if (pdhcpc->sockfd < 0)
560	        {
561	          ninfo("socket handle %d\n", pdhcpc->sockfd);
562	          free(pdhcpc);
563	          return NULL;
564	        }
565	
566	      /* Bind the socket */
567	
568	      addr.sin_family      = AF_INET;
569	      addr.sin_port        = HTONS(DHCPC_CLIENT_PORT);
570	      addr.sin_addr.s_addr = INADDR_ANY;
571	
572	      ret = bind(pdhcpc->sockfd, (struct sockaddr *)&addr,
573	                 sizeof(struct sockaddr_in));
574	      if (ret < 0)
575	        {
576	          ninfo("bind status %d\n", ret);
577	          close(pdhcpc->sockfd);
578	          free(pdhcpc);
579	          return NULL;
580	        }
581	
582	      /* Configure for read timeouts */
583	
584	      tv.tv_sec  = CONFIG_NETUTILS_DHCPC_RECV_TIMEOUT_MS / 1000;
585	      tv.tv_usec = (CONFIG_NETUTILS_DHCPC_RECV_TIMEOUT_MS % 1000) * 1000;
586	
587	      ret = setsockopt(pdhcpc->sockfd, SOL_SOCKET, SO_RCVTIMEO, &tv,
588	                       sizeof(struct timeval));
589	      if (ret < 0)
590	        {
591	          ninfo("setsockopt(RCVTIMEO) status %d\n", ret);
592	          close(pdhcpc->sockfd);
593	          free(pdhcpc);
594	          return NULL;
595	        }
596	
597	#ifdef CONFIG_NET_BINDTODEVICE
598	      /* Bind socket to interface, because UDP packets have to be sent to the
599	       * broadcast address at a moment when it is not possible to decide the
600	       * target network device using the local or remote address (which is,
601	       * by definition and purpose of DHCP, undefined yet).
602	       */
603	
604	      ret = setsockopt(pdhcpc->sockfd, SOL_SOCKET, SO_BINDTODEVICE,
605	                       pdhcpc->interface, strlen(pdhcpc->interface));
606	      if (ret < 0)
607	        {
608	          ninfo("setsockopt(BINDTODEVICE) status %d\n", ret);
609	          close(pdhcpc->sockfd);
610	          free(pdhcpc);
611	          return NULL;
612	        }
613	#endif
614	    }
615	
616	  return (FAR void *)pdhcpc;
617	}
