619	/****************************************************************************
620	 * Name: dhcpc_close
621	 ****************************************************************************/
622	
623	void dhcpc_close(FAR void *handle)
624	{
625	  struct dhcpc_state_s *pdhcpc = (struct dhcpc_state_s *)handle;
626	
627	  if (pdhcpc)
628	    {
629	      if (pdhcpc->thread)
630	        {
631	          dhcpc_cancel(pdhcpc);
632	        }
633	
634	      if (pdhcpc->sockfd)
635	        {
636	          close(pdhcpc->sockfd);
637	        }
638	
639	      free(pdhcpc);
640	    }
641	}
