643	/****************************************************************************
644	 * Name: dhcpc_cancel
645	 ****************************************************************************/
646	
647	void dhcpc_cancel(FAR void *handle)
648	{
649	  struct dhcpc_state_s *pdhcpc = (struct dhcpc_state_s *)handle;
650	#ifndef CONFIG_DISABLE_SIGNALS
651	  sighandler_t old;
652	#endif
653	  int ret;
654	
655	  if (pdhcpc)
656	    {
657	      pdhcpc->cancel = true;
658	
659	      if (pdhcpc->thread)
660	        {
661	#ifdef CONFIG_DISABLE_SIGNALS
662	          pthread_cancel(pdhcpc->thread);
663	#else
664	          old = signal(SIGQUIT, SIG_IGN);
665	
666	          /* Signal the dhcpc_run */
667	
668	          ret = pthread_kill(pdhcpc->thread, SIGQUIT);
669	          if (ret != 0)
670	            {
671	              nerr("ERROR: pthread_kill DHCPC thread\n");
672	            }
673	#endif
674	
675	          /* Wait for the end of dhcpc_run */
676	
677	          ret = pthread_join(pdhcpc->thread, NULL);
678	          if (ret != 0)
679	            {
680	              nerr("ERROR: pthread_join DHCPC thread\n");
681	            }
682	
683	          pdhcpc->thread = 0;
684	#ifndef CONFIG_DISABLE_SIGNALS
685	          signal(SIGQUIT, old);
686	#endif
687	        }
688	    }
689	}
