691	/****************************************************************************
692	 * Name: dhcpc_request
693	 ****************************************************************************/
694	
695	int dhcpc_request(FAR void *handle, FAR struct dhcpc_state *presult)
696	{
697	  FAR struct dhcpc_state_s *pdhcpc = (FAR struct dhcpc_state_s *)handle;
698	  struct in_addr oldaddr;
699	  ssize_t result;
700	  uint8_t msgtype;
701	  int     retries;
702	  int     state;
703	  clock_t start;
704	
705	  memset(presult, 0, sizeof(*presult));
706	
707	  /* RFC2131: For example, a client may choose a different,
708	   * random initial 'xid' each time the client is rebooted, and
709	   * subsequently use sequential 'xid's until the next reboot.
710	   */
711	
712	  pdhcpc->xid[3]++;
713	
714	  /* Save the currently assigned IP address. It should be INADDR_ANY
715	   * if this is the initial request, or a valid IP if this is a renewal.
716	   */
717	
718	  oldaddr.s_addr = 0;
719	  netlib_get_ipv4addr(pdhcpc->interface, &oldaddr);
720	
721	  /* Loop sending the DISCOVER up to CONFIG_NETUTILS_DHCPC_RETRIES
722	   * times
723	   */
724	
725	  retries = 0;
726	
727	  /* Loop sending DISCOVER until we receive an OFFER from a DHCP
728	   * server.  We will lock on to the first OFFER and decline any
729	   * subsequent offers (which will happen if there are more than one
730	   * DHCP servers on the network.
731	   */
732	
733	  state = STATE_INITIAL;
734	  do
735	    {
736	      if (pdhcpc->cancel)
737	        {
738	          errno = EINTR;
739	          return ERROR;
740	        }
741	
742	      /* Send the DISCOVER command */
743	
744	      ninfo("Broadcast DISCOVER\n");
745	      if (dhcpc_sendmsg(pdhcpc, presult, DHCPDISCOVER) < 0)
746	        {
747	          return ERROR;
748	        }
749	
750	      retries++;
751	
752	      /* Get the DHCPOFFER response */
753	
754	      start = clock();
755	      do
756	        {
757	          result = recv(pdhcpc->sockfd, &pdhcpc->packet,
758	                        sizeof(struct dhcp_msg), 0);
759	          if (result >= 0)
760	            {
761	              msgtype = dhcpc_parsemsg(pdhcpc, result, presult);
762	              if (msgtype == DHCPOFFER)
763	                {
764	                  /* Save the servid from the presult so that it is not
765	                   * clobbered by a new OFFER.
766	                   */
767	
768	                  ninfo("Received OFFER from %08" PRIx32 "\n",
769	                        (uint32_t)ntohl(presult->serverid.s_addr));
770	                  pdhcpc->ipaddr.s_addr   = presult->ipaddr.s_addr;
771	                  pdhcpc->serverid.s_addr = presult->serverid.s_addr;
772	
773	                  state = STATE_HAVE_OFFER;
774	                }
775	            }
776	
777	          /* An error has occurred.  If this was a timeout error (meaning
778	           * that nothing was received on this socket for a long period
779	           * of time). Then loop and send the DISCOVER command again.
780	           */
781	
782	          else if (errno != EAGAIN && errno != EINTR)
783	            {
784	              /* An error other than a timeout was received -- error out */
785	
786	              return ERROR;
787	            }
788	        }
789	      while (state == STATE_INITIAL && TICK2MSEC(clock() - start) <
790	             CONFIG_NETUTILS_DHCPC_RECV_TIMEOUT_MS);
791	    }
792	  while (state == STATE_INITIAL &&
793	         retries < CONFIG_NETUTILS_DHCPC_RETRIES);
794	
795	  /* If no DHCPOFFER received here, error out */
796	
797	  if (state == STATE_INITIAL)
798	    {
799	      return ERROR;
800	    }
801	
802	  /* Loop sending the REQUEST up to CONFIG_NETUTILS_DHCPC_RETRIES times
803	   * (if there is no response)
804	   */
805	
806	  retries = 0;
807	  do
808	    {
809	      if (pdhcpc->cancel)
810	        {
811	          errno = EINTR;
812	          return ERROR;
813	        }
814	
815	      /* Send the REQUEST message to obtain the lease that was offered to
816	       * us.
817	       */
818	
819	      ninfo("Send REQUEST\n");
820	      if (dhcpc_sendmsg(pdhcpc, presult, DHCPREQUEST) < 0)
821	        {
822	          return ERROR;
823	        }
824	
825	      retries++;
826	
827	      /* Get the ACK/NAK response to the REQUEST (or timeout) */
828	
829	      start = clock();
830	      do
831	        {
832	          result = recv(pdhcpc->sockfd, &pdhcpc->packet,
833	                        sizeof(struct dhcp_msg), 0);
834	          if (result >= 0)
835	            {
836	              /* Parse the response */
837	
838	              msgtype = dhcpc_parsemsg(pdhcpc, result, presult);
839	
840	              /* The ACK response means that the server has accepted
841	               * our request and we have the lease.
842	               */
843	
844	              if (msgtype == DHCPACK)
845	                {
846	                  ninfo("Received ACK\n");
847	                  if (oldaddr.s_addr != presult->ipaddr.s_addr)
848	                    {
849	                      netlib_set_ipv4addr(pdhcpc->interface,
850	                                          &presult->ipaddr);
851	                    }
852	
853	                  state = STATE_HAVE_LEASE;
854	                }
855	
856	              /* NAK means the server has refused our request */
857	
858	              else if (msgtype == DHCPNAK)
859	                {
860	                  ninfo("Received NAK\n");
861	                  oldaddr.s_addr = INADDR_ANY;
862	                  netlib_set_ipv4addr(pdhcpc->interface, &oldaddr);
863	                  errno = ECONNREFUSED;
864	                  return ERROR;
865	                }
866	
867	              /* If we get any OFFERs from other servers, then decline
868	               * them now and continue waiting for the ACK from the server
869	               * that we requested from.
870	               */
871	
872	              else if (msgtype == DHCPOFFER &&
873	                       pdhcpc->serverid.s_addr != presult->serverid.s_addr)
874	                {
875	                  ninfo("Received another OFFER, send DECLINE\n");
876	                  dhcpc_sendmsg(pdhcpc, presult, DHCPDECLINE);
877	                }
878	
879	              /* Otherwise, it is something that we do not recognize */
880	
881	              else
882	                {
883	                  ninfo("Ignoring msgtype=%d\n", msgtype);
884	                }
885	            }
886	
887	          /* An error has occurred.  If this was a timeout error (meaning
888	           * that nothing was received on this socket for a long period of
889	           * time). Then break out and send the DISCOVER command again
890	           * (at most 3 times).
891	           */
892	
893	          else if (errno != EAGAIN && errno != EINTR)
894	            {
895	              /* An error other than a timeout was received */
896	
897	              netlib_set_ipv4addr(pdhcpc->interface, &oldaddr);
898	              return ERROR;
899	            }
900	        }
901	      while (state == STATE_HAVE_OFFER && TICK2MSEC(clock() - start) <
902	             CONFIG_NETUTILS_DHCPC_RECV_TIMEOUT_MS);
903	    }
904	  while (state == STATE_HAVE_OFFER &&
905	         retries < CONFIG_NETUTILS_DHCPC_RETRIES);
906	
907	  /* If no DHCPLEASE received here, error out */
908	
909	  if (state != STATE_HAVE_LEASE)
910	    {
911	      return ERROR;
912	    }
913	
914	  ninfo("Got IP address %u.%u.%u.%u\n",
915	        ip4_addr1(presult->ipaddr.s_addr),
916	        ip4_addr2(presult->ipaddr.s_addr),
917	        ip4_addr3(presult->ipaddr.s_addr),
918	        ip4_addr4(presult->ipaddr.s_addr));
919	  ninfo("Got netmask %u.%u.%u.%u\n",
920	        ip4_addr1(presult->netmask.s_addr),
921	        ip4_addr2(presult->netmask.s_addr),
922	        ip4_addr3(presult->netmask.s_addr),
923	        ip4_addr4(presult->netmask.s_addr));
924	  ninfo("Got DNS server %u.%u.%u.%u\n",
925	        ip4_addr1(presult->dnsaddr.s_addr),
926	        ip4_addr2(presult->dnsaddr.s_addr),
927	        ip4_addr3(presult->dnsaddr.s_addr),
928	        ip4_addr4(presult->dnsaddr.s_addr));
929	  ninfo("Got default router %u.%u.%u.%u\n",
930	        ip4_addr1(presult->default_router.s_addr),
931	        ip4_addr2(presult->default_router.s_addr),
932	        ip4_addr3(presult->default_router.s_addr),
933	        ip4_addr4(presult->default_router.s_addr));
934	  ninfo("Lease expires in %" PRId32 " seconds\n", presult->lease_time);
935	  return OK;
936	}
