938	/****************************************************************************
939	 * Name: dhcpc_request_async
940	 ****************************************************************************/
941	
942	int dhcpc_request_async(FAR void *handle, dhcpc_callback_t callback)
943	{
944	  FAR struct dhcpc_state_s *pdhcpc = (FAR struct dhcpc_state_s *)handle;
945	  int ret;
946	
947	  if (!handle || !callback)
948	    {
949	      errno = EINVAL;
950	      return ERROR;
951	    }
952	
953	  if (pdhcpc->thread)
954	    {
955	      nerr("ERROR: DHCPC thread already running\n");
956	      errno = EALREADY;
957	      return ERROR;
958	    }
959	
960	  pdhcpc->callback = callback;
961	  pdhcpc->cancel   = 0;
962	  ret = pthread_create(&pdhcpc->thread, NULL, dhcpc_run, pdhcpc);
963	  if (ret != 0)
964	    {
965	      nerr("ERROR: Failed to start the DHCPC thread\n");
966	      errno = ret;
967	      return ERROR;
968	    }
969	
970	  return OK;
971	}
