35	/****************************************************************************
36	 * Name: dhcp_setup_result
37	 *
38	 * Description:
39	 *   Set network connection parameters
40	 *
41	 * Parameters:
42	 *   ifname   The name of the interface to use
43	 *   ds       The configure network parameter values
44	 *
45	 * Return:
46	 *   0 on success
47	 *   Negative integer on failure
48	 *
49	 ****************************************************************************/
50	
51	static int dhcp_setup_result(FAR const char *ifname,
52	                             FAR struct dhcpc_state *ds)
53	{
54	  int ret = netlib_set_ipv4addr(ifname, &ds->ipaddr);
55	  if (ret < 0)
56	    {
57	      nerr("ERROR: set IPv4 address failed: %d\n", ret);
58	      return ret;
59	    }
60	
61	  if (ds->netmask.s_addr != 0)
62	    {
63	      ret = netlib_set_ipv4netmask(ifname, &ds->netmask);
64	      if (ret < 0)
65	        {
66	          nerr("ERROR: set IPv4 netmask failed: %d\n", ret);
67	          return ret;
68	        }
69	    }
70	
71	  if (ds->default_router.s_addr != 0)
72	    {
73	      ret = netlib_set_dripv4addr(ifname, &ds->default_router);
74	      if (ret < 0)
75	        {
76	          nerr("ERROR: set default router address failed: %d\n", ret);
77	          return ret;
78	        }
79	    }
80	
81	#ifdef CONFIG_NETDB_DNSCLIENT
82	  if (ds->dnsaddr.s_addr != 0)
83	    {
84	      ret = netlib_set_ipv4dnsaddr(&ds->dnsaddr);
85	      if (ret < 0)
86	        {
87	          nerr("ERROR: set the DNS server address failed: %d\n", ret);
88	          return ret;
89	        }
90	    }
91	#endif
92	
93	  return OK;
94	}
