163	 *
164	 * Description:
165	 *   Perform DHCP in an attempt to get the IP
166	 *   address of the specified network device.
167	 *
168	 * Parameters:
169	 *   ifname   The name of the interface to use
170	 *
171	 * Return:
172	 *   0 on success
173	 *   Negative integer on failure
174	 *
175	 ****************************************************************************/
176	
177	int netlib_obtain_ipv4addr(FAR const char *ifname)
178	{
179	  if (ifname == NULL)
180	    {
181	      nerr("ERROR: Invalid network card name\n");
182	      return -EINVAL;
183	    }
184	
185	  return dhcp_obtain_statefuladdr(ifname);
186	}
